function expect(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}

function isAdm(value: string): value is AdmLevel {
  return (ADM_LEVELS as readonly string[]).includes(value);
}

export function licenseClass(license: string): LicenseClass {
  const text = license.trim();
  if (text === 'Other - Direct Permission' || text === 'Pixabay License for Content') return 'not-a-reusable-grant';
  if (/ShareAlike|Open Database License|ODbL/i.test(text)) return 'share-alike';
  if (/CC0|Public Domain|PDDL/i.test(text)) return 'public-domain';
  if (/Creative Commons Attribution|Open Government Licence|Open Government License|Etalab|Data license Germany|Open Government Canada|Korea Open Government|Singapore Open Data|Open Data Commons Attribution/i.test(text)) {
    return 'attribution';
  }
  return 'unreviewed-source-terms';
}

export function isMunicipalCanonical(canonical: string): boolean {
  return MUNICIPAL_CANONICALS.includes(canonical.trim());
}

export function layoutLevel(file: BoundaryFile): LayoutLevel {
  if (file.adm === 'ADM0') return 'country';
  if (isMunicipalCanonical(file.canonical)) return 'place';
  return 'admin';
}

export function admission(file: BoundaryFile): Admission {
  const kind = licenseClass(file.license);
  if (kind === 'not-a-reusable-grant' || kind === 'unreviewed-source-terms') return 'withhold';
  if (kind === 'share-alike') return 'share-alike';
  return 'admit';
}

export function relativeMetadataPath(file: BoundaryFile): string {
  const rel = 'geography/' + layoutLevel(file) + '/' + file.iso + '/' + file.adm + '-metaData.json';
  expectSafeRelative(rel);
  return rel;
}

function expectSafeRelative(value: string): void {
  expect(value.length > 0 && !value.startsWith('/') && !value.includes('\\') && !value.split('/').includes('..'), 'unsafe layout path ' + value);
}

export function readBoundaryFiles(input: unknown): BoundaryFile[] {
  expect(Array.isArray(input), 'boundary index is not an array');
  const files: BoundaryFile[] = [];
  const seen = new Set<string>();
  for (const item of input) {
    expect(item !== null && typeof item === 'object', 'boundary row is not an object');
    const row = item as Record<string, unknown>;
    const iso = row.iso;
    const adm = row.adm;
    const units = row.units;
    const canonical = row.canonical;
    const license = row.license;
    const boundaryId = row.boundaryId;
    const sha256 = row.sha256;
    const bytes = row.bytes;
    expect(typeof iso === 'string' && /^[A-Z]{3}$/.test(iso), 'bad iso');
    expect(typeof adm === 'string' && isAdm(adm), 'bad adm for ' + String(iso));
    expect(typeof units === 'number' && Number.isInteger(units) && units >= 0, 'bad units for ' + String(iso));
    expect(typeof canonical === 'string', 'bad canonical for ' + String(iso));
    expect(typeof license === 'string' && license.trim().length > 0, 'bad license for ' + String(iso));
    expect(typeof boundaryId === 'string' && boundaryId.startsWith(iso + '-' + adm + '-'), 'bad boundary id ' + String(boundaryId));
    expect(typeof sha256 === 'string' && /^[0-9a-f]{64}$/.test(sha256), 'bad sha256 for ' + String(iso));
    expect(typeof bytes === 'number' && Number.isInteger(bytes) && bytes > 0, 'bad bytes for ' + String(iso));
    const key = iso + ' ' + adm;
    expect(!seen.has(key), 'duplicate boundary file ' + key);
    seen.add(key);
    files.push({ iso, adm, units, canonical, license, boundaryId, sha256, bytes });
  }
  return files;
}

export function metadataRollup(files: readonly BoundaryFile[]): string {
  const lines = [...files]
    .sort((left, right) => left.iso.localeCompare(right.iso) || left.adm.localeCompare(right.adm))
    .map((file) => file.iso + '|' + file.adm + '|' + file.sha256);
  return createHash('sha256').update(lines.join('\n') + '\n').digest('hex');
}

function rowOf(iso: string, adm: AdmLevel): BoundaryFile {
  const found = BOUNDARY_FILES.find((file) => file.iso === iso && file.adm === adm);
  expect(found !== undefined, 'missing ' + iso + ' ' + adm);
  return found as BoundaryFile;
}

function sameList(left: readonly string[], right: readonly string[]): boolean {
  return left.length === right.length && left.every((item, index) => item === right[index]);
}

export function verifyPinnedIndex(): void {
  expect(BOUNDARY_FILES.length === 712, 'expected 712 metadata files');
  expect(metadataRollup(BOUNDARY_FILES) === METADATA_ROLLUP_SHA256, 'metadata rollup drifted');
  expect(new Set(BOUNDARY_FILES.map((file) => file.iso)).size === 231, 'expected 231 country directories');
  expect(BOUNDARY_FILES.reduce((sum, file) => sum + file.bytes, 0) === 635323, 'metadata byte total drifted');
  for (const level of ADM_LEVELS) {
    const expected = { ADM0: 230, ADM1: 198, ADM2: 180, ADM3: 80, ADM4: 20, ADM5: 4 }[level];
    expect(BOUNDARY_FILES.filter((file) => file.adm === level).length === expected, 'level count drifted for ' + level);
  }
  for (const label of MUNICIPAL_CANONICALS) {
    expect(BOUNDARY_FILES.some((file) => file.canonical === label), 'municipal label missing from the pin: ' + label);
  }
  const municipal = BOUNDARY_FILES.filter((file) => isMunicipalCanonical(file.canonical));
  expect(municipal.length === 61, 'expected 61 municipal-label files');
  expect(new Set(municipal.map((file) => file.iso)).size === 56, 'expected 56 municipal-label directories');
  const classes = { attribution: 0, 'share-alike': 0, 'public-domain': 0, 'not-a-reusable-grant': 0, 'unreviewed-source-terms': 0 };
  for (const file of BOUNDARY_FILES) classes[licenseClass(file.license)] += 1;
  expect(classes.attribution === 305, 'attribution license count drifted');
  expect(classes['share-alike'] === 280, 'share-alike count drifted');
  expect(classes['public-domain'] === 116, 'public-domain count drifted');
  expect(classes['not-a-reusable-grant'] === 6, 'non-reusable count drifted');
  expect(classes['unreviewed-source-terms'] === 5, 'unreviewed count drifted');
  const withheld = BOUNDARY_FILES.filter((file) => admission(file) === 'withhold')
    .map((file) => file.iso + ' ' + file.adm)
    .sort();
  expect(sameList(withheld, [...EXPECTED_WITHHELD].sort()), 'withheld files drifted: ' + withheld.join(','));
  const adm0Only = [...groupByIso().entries()]
    .filter(([, levels]) => levels.size === 1 && levels.has('ADM0'))
    .map(([iso]) => iso)
    .sort();
  expect(sameList(adm0Only, EXPECTED_ADM0_ONLY), 'ADM0-only directories drifted');
  const missingAdm0 = [...groupByIso().entries()].filter(([, levels]) => !levels.has('ADM0')).map(([iso]) => iso);
  expect(sameList(missingAdm0, ['PRI']), 'expected only PRI to lack ADM0');
  const nld = rowOf('NLD', 'ADM2');
  expect(nld.canonical === 'Municipality' && nld.units === 344 && licenseClass(nld.license) === 'public-domain', 'NLD ADM2 pin drifted');
  const usa = rowOf('USA', 'ADM2');
  expect(usa.canonical === 'Counties' && usa.units === 3233 && !isMunicipalCanonical(usa.canonical), 'USA ADM2 pin drifted');
  expect(rowOf('USA', 'ADM0').canonical === 'United States of America', 'USA ADM0 pin drifted');
  const deuMunicipal = BOUNDARY_FILES.filter((file) => file.iso === 'DEU' && isMunicipalCanonical(file.canonical));
  expect(deuMunicipal.length === 0, 'DEU was not given a municipal label');
  expect(rowOf('DEU', 'ADM2').canonical === 'Government District', 'DEU ADM2 pin drifted');
  expect(rowOf('DEU', 'ADM3').canonical === 'Independent City or District', 'DEU ADM3 pin drifted');
  const che = rowOf('CHE', 'ADM3');
  expect(che.canonical === 'Municipality' && che.units === 2286 && licenseClass(che.license) === 'unreviewed-source-terms', 'CHE ADM3 pin drifted');
  expect(rowOf('ALB', 'ADM0').canonical === 'Shqipëria', 'ALB canonical drifted');
  expect(rowOf('VNM', 'ADM0').canonical === 'Việt Nam', 'VNM canonical drifted');
  expect(rowOf('TWN', 'ADM0').license === 'Pixabay License for Content', 'TWN ADM0 license drifted');
  const fra = rowOf('FRA', 'ADM5');
  expect(fra.units === 35010 && fra.canonical.startsWith('Arrondissement municipal'), 'FRA ADM5 pin drifted');
  const openMunicipalCountries = new Set(municipal.filter((file) => admission(file) !== 'withhold').map((file) => file.iso));
  expect(openMunicipalCountries.size === 55, 'expected 55 directories with an open municipal-label file');
  expect(!openMunicipalCountries.has('CHE'), 'CHE municipal geometry stays withheld');
}

function groupByIso(): Map<string, Set<AdmLevel>> {
  const grouped = new Map<string, Set<AdmLevel>>();
  for (const file of BOUNDARY_FILES) {
    const levels = grouped.get(file.iso) || new Set<AdmLevel>();
    levels.add(file.adm);
    grouped.set(file.iso, levels);
  }
  return grouped;
}

function nativeAliasSample(): Array<Record<string, unknown>> {
  return NATIVE_OBSERVATIONS.map((item) => {
    const row = rowOf(item.iso, item.adm);
    if (item.field === 'boundaryCanonical') expect(row.canonical === item.name, 'native canonical drifted for ' + item.iso);
    expect(/^[a-z]{2,3}$/.test(item.lang), 'language code must be 2 or 3 letters');
    expect(/^[0-9a-f]{64}$/.test(item.geometrySha256), 'geometry sha256 must be pinned');
    expectSafeRelative(item.upstreamPath);
    return {
      name: item.name,
      lang: item.lang,
      iso: item.iso,
      adm: item.adm,
      field: item.field,
      english_shape_name: item.englishShapeName,
      metadata_sha256: row.sha256,
      geometry_sha256: item.geometrySha256,
      geometry_bytes: item.geometryBytes,
      upstream_path: item.upstreamPath,
      note: item.note,
    };
  });
}

function census() {
  const countries = new Set(BOUNDARY_FILES.map((file) => file.iso));
  const byLevel: Record<string, number> = {};
  for (const level of ADM_LEVELS) byLevel[level] = BOUNDARY_FILES.filter((file) => file.adm === level).length;
  const licenseClasses = {
    attribution: 0,
    'share-alike': 0,
    'public-domain': 0,
    'not-a-reusable-grant': 0,
    'unreviewed-source-terms': 0,
  };
  for (const file of BOUNDARY_FILES) licenseClasses[licenseClass(file.license)] += 1;
  const municipal = BOUNDARY_FILES.filter((file) => isMunicipalCanonical(file.canonical));
  const municipalCountries = new Set(municipal.map((file) => file.iso));
  const openMunicipalCountries = new Set(municipal.filter((file) => admission(file) !== 'withhold').map((file) => file.iso));
  const adm0Only = [...groupByIso().entries()]
    .filter(([, levels]) => levels.size === 1 && levels.has('ADM0'))
    .map(([iso]) => iso)
    .sort();
  const missingAdm0 = [...groupByIso().entries()].filter(([, levels]) => !levels.has('ADM0')).map(([iso]) => iso).sort();
  return {
    files: BOUNDARY_FILES.length,
    countries: countries.size,
    metadataBytes: BOUNDARY_FILES.reduce((sum, file) => sum + file.bytes, 0),
    byLevel,
    licenseClasses,
    municipalFiles: municipal.length,
    municipalCountries: municipalCountries.size,
    openMunicipalFiles: municipal.filter((file) => admission(file) !== 'withhold').length,
    openMunicipalCountries: openMunicipalCountries.size,
    adm0Only,
    missingAdm0,
  };
}

function municipalityLimit(summary: ReturnType<typeof census>): string {
  return summary.municipalCountries + ' of ' + summary.countries
    + ' gbOpen directories have a boundaryCanonical in the closed municipal label set ('
    + summary.municipalFiles + ' files). ' + summary.openMunicipalCountries
    + ' of those directories have at least one attribution, public-domain, or share-alike file. '
    + 'CHE ADM3 is labeled Municipality (2286 units) and is withheld because the swisstopo terms were not read. '
    + 'The other ' + (summary.countries - summary.municipalCountries)
    + ' directories, including USA where ADM2 is Counties (3233 units), have no municipal label. '
    + summary.adm0Only.length + ' directories are ADM0 only, and ' + summary.missingAdm0.join(', ')
    + ' has no ADM0 file. An ADM number is not a municipality, and a label is not a claim that every municipality is present.';
}

function coverageLimits(summary: ReturnType<typeof census>): string[] {
  const exonyms = EXONYM_SAMPLES.map((sample) => sample.iso + ' (' + sample.features + ' features, sha256 ' + sample.sha256 + ')').join(', ');
  return [
    'The pinned source is geoBoundaries gbOpen release ' + RELEASE + ', git commit ' + REVISION + ', committed ' + COMMITTED_AT + '. The geoboundaries.org current API is a later build and is not this revision.',
    summary.countries + ' country directories and ' + summary.files + ' metadata files were read (' + summary.metadataBytes + ' bytes) on ' + ACQUIRED_ON + '. ' + summary.adm0Only.length + ' directories are ADM0 only. ' + summary.missingAdm0.join(', ') + ' has no ADM0 file. complete_world is false.',
    'An ADM number is not a municipality. USA ADM2 is Counties (3233 units, public domain). NLD ADM2 is Municipality (344 units, CC0). DEU has no municipal label: ADM2 is Government District and ADM3 is Independent City or District.',
    municipalityLimit(summary) + ' The FRA ADM5 canonical names several unit types in one string and is not a pure commune layer.',
    'shapeName has no language code and no alternate-name list. English shapeName Albania is paired with canonical Shqipëria, and English shapeName Vietnam is paired with canonical Việt Nam. NLD ADM2 shape names include \'s-Gravenhage and Noardeast-Fryslân and do not include Den Haag. Language codes on the samples are identified from the name form because the file does not carry one.',
    'Opened simplified ADM1 files whose shape names are ASCII exonyms: ' + exonyms + '. The CHN file includes a shape named Taiwan Province. This registry does not decide that claim. TWN is a separate directory and its ADM0 file is withheld.',
    'Project LICENSE sha256 ' + LICENSE_FILE_SHA256 + ' and CITATION-AND-USE sha256 ' + CITATION_FILE_SHA256 + ' state CC-BY-4.0 and require attribution to geoBoundaries plus each file boundarySource. That statement does not replace a file boundaryLicense. ' + summary.licenseClasses['share-alike'] + ' files are share-alike, ' + summary.licenseClasses['public-domain'] + ' are public domain or CC0, and ' + summary.licenseClasses.attribution + ' use an attribution license.',
    summary.licenseClasses['unreviewed-source-terms'] + ' files use source terms this registry has not read (every CHE level, and ESP ADM2). ' + summary.licenseClasses['not-a-reusable-grant'] + ' files are not a reusable grant: OMN ADM2, SLB ADM3, SLB ADM4, TUV ADM3, and VUT ADM3 say Other - Direct Permission, and TWN ADM0 says Pixabay License for Content. Those files are indexed and withheld.',
    'shapeISO was empty on the opened NLD ADM2 feature Groningen. ISO 3166-2 is not guaranteed. shapeID identifies a geometry and boundaryID identifies a file.',
    'The default download is hierarchical and small: per-country metadata JSON under geography/country/, geography/admin/, and geography/place/. The metadata layer is ' + summary.metadataBytes + ' bytes. Simplified and full-resolution geometries, shapefiles, and global composites are outside that layout. The opened NLD ADM2 simplified geometry alone is 767672 bytes.',
    'Postal codes are not in gbOpen. Enclaves, holes, antimeridian cuts, and disputed borders were not topology-tested. Some upstream licenseSource values omit the colon in https and are not copied as URLs. boundaryCanonical is sometimes a unit type and sometimes a country name.',
  ];
}

function withheldRows(): Array<Record<string, unknown>> {
  return BOUNDARY_FILES.filter((file) => admission(file) === 'withhold')
    .sort((left, right) => left.iso.localeCompare(right.iso) || left.adm.localeCompare(right.adm))
    .map((file) => ({
      iso: file.iso,
      adm: file.adm,
      boundary_id: file.boundaryId,
      canonical: file.canonical,
      license: file.license,
      license_class: licenseClass(file.license),
      level: layoutLevel(file),
      path: relativeMetadataPath(file),
      admission: 'withhold',
    }));
}

export function buildPlaces(): Record<string, unknown> {
  verifyPinnedIndex();
  const summary = census();
  const manifest = {
    schema: GEOGRAPHY_SCHEMA,
    dataset_id: DATASET_ID,
    revision: REVISION,
    release: RELEASE,
    product: PRODUCT,
    license: LICENSE,
    attribution: ATTRIBUTION,
    municipality_detail: 'partial',
    municipality_limit: municipalityLimit(summary),
    native_alias_sample: nativeAliasSample(),
    coverage_limits: coverageLimits(summary),
    hierarchical: true,
    complete_world: false,
    layout: [
      { level: 'country', path: 'geography/country/' },
      { level: 'admin', path: 'geography/admin/' },
      { level: 'place', path: 'geography/place/' },
    ],
    source: {
      repository: DATASET_ID,
      tag: 'v6.0.0',
      committed_at: COMMITTED_AT,
      acquired_on: ACQUIRED_ON,
      license_file_sha256: LICENSE_FILE_SHA256,
      citation_file_sha256: CITATION_FILE_SHA256,
      read_from: 'git-lfs-media-at-revision',
      links: SOURCE_LINKS,
    },
    identifiers: {
      file_id: 'boundaryID',
      geometry_id: 'shapeID',
      country_code: 'boundaryISO',
      subdivision_code: 'shapeISO',
      subdivision_code_guaranteed: false,
    },
    download: {
      hierarchical: true,
      default_payload: 'metadata-json',
      metadata_bytes: summary.metadataBytes,
      geometry_in_default_layout: false,
      full_resolution_in_default_layout: false,
      global_composite_in_default_layout: false,
      patterns: {
        country: 'geography/country/{iso}/{adm}-metaData.json',
        admin: 'geography/admin/{iso}/{adm}-metaData.json',
        place: 'geography/place/{iso}/{adm}-metaData.json',
      },
    },
    census: {
      metadata_files: summary.files,
      country_directories: summary.countries,
      metadata_bytes: summary.metadataBytes,
      metadata_rollup_sha256: METADATA_ROLLUP_SHA256,
      by_level: summary.byLevel,
      license_classes: summary.licenseClasses,
      municipal_files: summary.municipalFiles,
      municipal_countries: summary.municipalCountries,
      open_municipal_files: summary.openMunicipalFiles,
      open_municipal_countries: summary.openMunicipalCountries,
      adm0_only: summary.adm0Only,
      missing_adm0: summary.missingAdm0,
      exonym_samples: EXONYM_SAMPLES,
    },
    withheld: withheldRows(),
  };
  for (const entry of manifest.layout) expectSafeRelative(entry.path);
  assertManifestContract(manifest);
  return manifest;
}

export function assertManifestContract(doc: Record<string, unknown>): void {
  expect(doc.schema === GEOGRAPHY_SCHEMA, 'schema');
  expect(doc.dataset_id === DATASET_ID, 'dataset_id');
  expect(typeof doc.revision === 'string' && /^[0-9a-f]{7,64}$/.test(doc.revision), 'revision');
  expect(typeof doc.license === 'string' && doc.license.trim().length > 0, 'license');
  expect(typeof doc.attribution === 'string' && doc.attribution.trim().length >= 3, 'attribution');
  expect(doc.municipality_detail === 'partial', 'municipality_detail');
  expect(typeof doc.municipality_limit === 'string' && doc.municipality_limit.trim().length > 0, 'municipality_limit');
  expect(Array.isArray(doc.native_alias_sample) && doc.native_alias_sample.length > 0, 'native_alias_sample');
  for (const alias of doc.native_alias_sample as Array<Record<string, unknown>>) {
    expect(typeof alias.name === 'string' && alias.name.trim().length > 0, 'alias name');
    expect(typeof alias.lang === 'string' && /^[a-z]{2,3}$/.test(alias.lang), 'alias lang');
  }
  expect(Array.isArray(doc.coverage_limits) && doc.coverage_limits.length > 0, 'coverage_limits');
  expect((doc.coverage_limits as unknown[]).every((item) => typeof item === 'string' && item.trim().length > 0), 'coverage limit text');
  expect(doc.hierarchical === true, 'hierarchical');
  expect(doc.complete_world === false, 'complete_world');
  const levels = new Set<string>();
  expect(Array.isArray(doc.layout), 'layout');
  for (const entry of doc.layout as Array<Record<string, unknown>>) {
    expect(entry.level === 'country' || entry.level === 'admin' || entry.level === 'place', 'layout level');
    expect(typeof entry.path === 'string', 'layout path');
    expectSafeRelative(entry.path);
    levels.add(String(entry.level));
  }
  for (const level of LAYOUT_LEVELS) expect(levels.has(level), 'missing layout level ' + level);
  expect(Array.isArray(doc.withheld) && doc.withheld.length === EXPECTED_WITHHELD.length, 'withheld list');
}

function repoRoot(): string {
  return path.resolve(fileURLToPath(new URL('../../', import.meta.url)));
}

function manifestPath(): string {
  return path.join(repoRoot(), 'data/worldwide/geography-manifest.json');
}

function writeAtomic(filePath: string, text: string): void {
  const tmp = filePath + '.tmp';
  writeFileSync(tmp, text);
  renameSync(tmp, filePath);
}

function runningAsCli(): boolean {
  const entry = process.argv[1];
  if (!entry) return false;
  return import.meta.url === pathToFileURL(path.resolve(entry)).href;
}

function main(): void {
  const write = process.argv.includes('--write');
  const check = process.argv.includes('--check');
  if (!write && !check) throw new Error('pass --write, --check, or both');
  const text = JSON.stringify(buildPlaces(), null, 2) + '\n';
  const target = manifestPath();
  if (write) writeAtomic(target, text);
  if (check) {
    const current = readFileSync(target, 'utf8');
    expect(current === text, 'geography manifest does not match the builder');
  }
  process.stdout.write(JSON.stringify({ ok: true, bytes: new TextEncoder().encode(text).length, files: BOUNDARY_FILES.length, path: path.relative(repoRoot(), target) }) + '\n');
}

